import React, { useState } from "react";
import {
  Container,
  TextField,
  Button,
  Card,
  CardContent,
  Typography,
  Box,
  Chip,
  Alert,
  CircularProgress
} from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";
import SearchIcon from "@mui/icons-material/Search";
import axios from "axios";

const Community = () => {
  const [query, setQuery] = useState("");
  const [disease, setDisease] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const API_URL = "http://localhost:5000/api/diseases";

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setError("");
    setDisease(null);

    try {
      const res = await axios.get(`${API_URL}/${query}`);
      setDisease(res.data);
    } catch (err) {
      setError("🌼 Disease not found. Try another name.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container maxWidth="md" sx={{ mt: 6 }}>
      {/* HEADER */}
      <Box textAlign="center" mb={4}>
        <Typography variant="h4" fontWeight="bold" color="primary">
          Community Health Guide
        </Typography>
        <Typography variant="body1" color="text.secondary" mt={1}>
          Search diseases and learn in a simple, friendly way 💙
        </Typography>
      </Box>

      {/* SEARCH BAR */}
      <Box display="flex" gap={2} mb={4}>
        <TextField
          fullWidth
          label="Enter disease name (e.g. Diabetes)"
          variant="outlined"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          sx={{
            backgroundColor: "#fff",
            borderRadius: 2
          }}
        />
        <Button
          variant="contained"
          startIcon={<SearchIcon />}
          onClick={handleSearch}
          sx={{
            px: 4,
            borderRadius: 3
          }}
        >
          Search
        </Button>
      </Box>

      {/* LOADING */}
      {loading && (
        <Box textAlign="center" mt={3}>
          <CircularProgress />
          <Typography mt={2}>Fetching health info…</Typography>
        </Box>
      )}

      {/* ERROR */}
      {error && <Alert severity="error">{error}</Alert>}

      {/* DISEASE CARD */}
      {disease && (
        <Card
          sx={{
            mt: 4,
            borderRadius: 4,
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
            background: "linear-gradient(135deg, #fdfbfb, #ebedee)"
          }}
        >
          <CardContent>
            <Box display="flex" alignItems="center" gap={1}>
              <FavoriteIcon color="error" />
              <Typography variant="h5" fontWeight="bold">
                {disease.name}
              </Typography>
            </Box>

            <Typography mt={2}>
              <b>Description:</b> {disease.description}
            </Typography>

            <Section title="Symptoms" items={disease.symptoms} />
            <Section title="Causes" items={disease.causes} />
            <Section title="Precautions" items={disease.precautions} />

            <Typography mt={3}>
              <b>Treatment:</b> {disease.treatment}
            </Typography>
          </CardContent>
        </Card>
      )}
    </Container>
  );
};

/* 💕 Reusable Cute Section */
const Section = ({ title, items }) => {
  if (!items || items.length === 0) return null;

  return (
    <Box mt={3}>
      <Typography fontWeight="bold">{title}</Typography>
      <Box display="flex" flexWrap="wrap" gap={1} mt={1}>
        {items.map((item, index) => (
          <Chip
            key={index}
            label={item}
            color="primary"
            variant="outlined"
            sx={{ borderRadius: 2 }}
          />
        ))}
      </Box>
    </Box>
  );
};

export default Community;
